package kr.or.arte.seal.statistics.application;import java.util.List;public record StatisticsSnapshot(List<StatusCount> requests,List<StatusCount> responses,List<StatusCount> mail,List<StatusCount> evidence,List<StatusCount> rights,List<StatusCount> retention){public StatisticsSnapshot{requests=List.copyOf(requests);responses=List.copyOf(responses);mail=List.copyOf(mail);evidence=List.copyOf(evidence);rights=List.copyOf(rights);retention=List.copyOf(retention);}}
